import ast, json, pathlib, sys, time
root, reproduced = map(pathlib.Path, sys.argv[1:])
sys.path.insert(0, str(root))
from common import digest, load, need, write_new
expected = {'local-image-list':1, 'archive-catalog':0, 'pyyaml-upstream':0, 'pip-upstream':0, 'wheel-verification':0, 'native-verification':0, 'bootstrap-verification':1, 'bootstrap-verification-final':0, 'material-gate':2, 'staged-wheel-verification':0, 'tool-tests-final':0, 'static-reproduction':0, 'source-validation':0, 'report-reproduction':0}
receipts = {}
for name, code in expected.items():
    path = root / name / 'receipt.json'
    receipt = load(path)
    need(receipt['complete'] is True and type(receipt['returncode']) is int and receipt['returncode'] == code, name)
    for item, value in receipt['sha256'].items():
        need(digest(path.parent / item) == value, 'Capture changed: ' + name)
    receipts[name] = {'returncode':code, 'receipt_sha256':digest(path)}
need('Ran 15 tests' in (root/'tool-tests-final'/'stderr').read_text() and '\nOK\n' in (root/'tool-tests-final'/'stderr').read_text(), 'Tool test completion absent')
reports = {}
for name in ('P4_IMAGE_COMPONENTS.json','P4_WHEEL_APPROVAL_MATRIX.md','P4_PIP_BOOTSTRAP.json'):
    need((root/name).read_bytes() == (reproduced/name).read_bytes(), 'Reproduction mismatch: ' + name)
    reports[name] = digest(root/name)
sources = list(root.rglob('*.py'))
for path in sources:
    ast.parse(path.read_text(encoding='ascii'), filename=str(path), feature_version=(3,11))
for path in root.rglob('*'):
    if path.is_file() and path.suffix in ('.py','.md','.json','.lock'):
        text = path.read_text(encoding='ascii')
        need(all(line.rstrip()==line for line in text.splitlines()), 'Trailing whitespace: ' + str(path))
        if path.suffix == '.json': load(path)
preserved = load(root/'PRESERVATION_VERIFIED.json')
need(preserved['files']==927 and preserved['status']=='PASS_SCOPED_REPOSITORY_BYTES_UNCHANGED','Historical preservation')
